import { EventObjState } from "../lib/types";

type TextInfomation = {
    fontFamily: string;
    fontColor: string;
    fontSize: number;
    lineSpaceValue: number;
    textLine: number;
}

type MessageWindowInfomation = {
    backColor: string;
    alphaValue: number;
    lineColor: string;
}

type ImageKeyData = {
    normal: string;
    smile: string;
    unger: string;
}

export class SettingData {
    constructor() { }

    //キャラクターの画像キーを取得
    public getImageKeyDataInfomation(scene: Phaser.Scene) {
        //normal: imageKeyData.normal,
        //smile: alphaValue,
        //unger: lineColor,
        return scene.cache.json.get('ImageKeyData');
    }

    //キャラクターの画像キーを取得
    public getCharacterImageKey(scene: Phaser.Scene, characterName: string) {

        const imageKeyData = scene.cache.json.get('ImageKeyData');

        for (const key in imageKeyData) {
            const k = key as keyof typeof imageKeyData;
            if (k === characterName) {
                // console.log(key, imageKeyData[k])
                return {
                    normal: imageKeyData[k].normal,
                    smile: imageKeyData[k].smile,
                    unger: imageKeyData[k].unger
                } as ImageKeyData;
            };
        }
    }

    //イベントデータ
    public getEventFlgFromSaveDataInfomation(scene: Phaser.Scene, eventName: string): number {
        let eventState: number = EventObjState.true;
        const eventFlgData = scene.cache.json.get('savedata').EventFlag;

        //savedataのfalse,trueを0,1で返す
        for (const key in eventFlgData) {
            const k = key as keyof typeof eventFlgData;
            if (k === eventName) {
                if (eventFlgData[k] === false) {
                    // console.log(key, eventFlgData[k])
                    eventState = EventObjState.false;
                }
            }
        }
        return eventState;
    }

    //指定イベントのフラグを更新
    public updateEventFlg(scene: Phaser.Scene, eventName: string, flg: boolean) {
        const eventFlgData = scene.cache.json.get('savedata').EventFlag;

        for (const key in eventFlgData) {
            const k = key as keyof typeof eventFlgData;
            if (k === eventName) {
                // console.log(key, eventFlgData[k])
                eventFlgData[k] = flg;
            }
        }
    }

    //名前データを取得
    public getSpriteNameData(scene: Phaser.Scene, characterName: string) {
        const fieldNameData = scene.cache.json.get('namedata').FieldNameData;

        for (const key in fieldNameData) {
            const k = key as keyof typeof fieldNameData;
            if (k === characterName) {
                console.log(key, fieldNameData[k])
                return fieldNameData[k];
            }
        }
    }


}

import { BehaviorSubject, Observable } from 'rxjs';
import { filter, map, take } from 'rxjs/operators';

type Status = {
  Lv: number,
  HP: number,
  MP: number,
  MaxHP: number,
  MaxMP: number,
  Attack: number,
  Guard: number,
  Speed: number
}

const PLAYER_STATEUS: Status = {
  Lv: 1,
  HP: 40,
  MP: 10,
  MaxHP: 50,
  MaxMP: 20,
  Attack: 30,
  Guard: 5,
  Speed: 10
};

export class ScoreStore {
  // 内部保持用。初期値をセット。
  private state$ = new BehaviorSubject<Status>(PLAYER_STATEUS);

  // 外部公開用のObservable。scoreだけを抜き出して公開。
  public readonly hp$: Observable<number> = this.state$.pipe(map(state => state.HP));

  // 状態更新メソッド
  //「今の状態をコピーして、HPだけを安全に計算し直し、新しい状態として再配布する」という一連の処理を安全に行っている
  public damage(amount: number): void {
    const currentState = this.state$.value;
    this.state$.next({
      ...currentState,//まずは全ての値を取得、※元の保持データ（参照先）の変更はこのように書く
      HP: Math.max(0, currentState.HP - amount)//値更新、０未満にはならないらしい
    });
  }

  //状態のリセットは必ず意識する事
  public reset(): void {
    this.state$.next(PLAYER_STATEUS);
  }

  // 現在の値を即時取得するためのゲッター
  public get currentHP(): number { return this.state$.value.HP; }
}

// 唯一のインスタンスを公開（シングルトン）
export const scoreStore = new ScoreStore();

import { BattleScene, GameScene, CharacterStatus } from "../../lib/types";
import { CharacterGameObject } from "../../event/view/CharacterGameObject";
import { Npc } from "../../gamemain/view/character/Npc";
import { FieldEnemyNameData } from "../../Data/NameData";

export class BattleModel {
    private battleScene: BattleScene;
    private gameScene: GameScene;
    private usePatern: string;
    private canNotRunaway: boolean = false;

    private characterGameObject: CharacterGameObject;
    private partyList: string[] = ['player'];//現状はプレイヤーのみ
    private playerPartyList: Phaser.GameObjects.Sprite[] = [];//現状はプレイヤーのみ
    private playerPartyMap: Map<string, Phaser.GameObjects.Sprite>;//マップと配列のどちらが良いか...？　色々考えたが番号で簡単に指定できる配列の方が良さそう。
    private nowSelectPartyMemberNo: number = 0;//左から数えた値

    private enemyList: string[] = [];//イベント戦闘の敵名称等
    private enemyPartyMap: Map<string, Phaser.GameObjects.Image>;
    private fieldHitEnemy: Npc;

    constructor(battleScene: BattleScene, data: { usePatern: string, fieldHitEnemy: Npc, canNotRunaway: boolean }) {
        this.battleScene = battleScene;
        this.gameScene = (this.battleScene.scene.get('Game') as GameScene);
        this.usePatern = data.usePatern;
        this.canNotRunaway = data.canNotRunaway;
        this.characterGameObject = new CharacterGameObject();
        this.fieldHitEnemy = data.fieldHitEnemy;

        //敵味方パーティを作成
        this.createBattlePartyData();
        if (this.usePatern === 'normal') {
            this.createBattleEnemyData();
        } else {
            this.createEventBattleEnemyData();
        }
    }

    public createBattlePartyData() {
        this.playerPartyMap = new Map();
        for (const name of this.partyList) {
            this.playerPartyMap.set(name, this.characterGameObject.getSprite(this.gameScene, name));
            this.playerPartyList.push(this.characterGameObject.getSprite(this.gameScene, name));
        }
    }

    //通常戦闘の敵データを作成
    public createBattleEnemyData() {
        this.enemyPartyMap = new Map();

        //敵数をランダムで作成
        const enemyValue = new Phaser.Math.RandomDataGenerator().between(1, 2);
        // const enemyValue = 2;

        for (let i = 0; i < enemyValue; i++) {

            //シンボルエンカウントした1体のみデータを引き継ぐ
            if (i === 0) {
                const data: CharacterStatus = {
                    level: this.fieldHitEnemy.getData('level'),
                    HP: this.fieldHitEnemy.getData('HP'),
                    MP: this.fieldHitEnemy.getData('MP'),
                    MaxHP: this.fieldHitEnemy.getData('MaxHP'),
                    MaxMP: this.fieldHitEnemy.getData('MaxMP'),
                    Attack: this.fieldHitEnemy.getData('Attack'),
                    Guard: this.fieldHitEnemy.getData('Guard'),
                    Speed: this.fieldHitEnemy.getData('Speed'),
                    gold: this.fieldHitEnemy.getData('gold')
                }

                //画像キー：画像　の形式で格納
                this.enemyPartyMap.set(this.fieldHitEnemy.getData('ImageKey'), this.battleScene.add.image(0, 0, this.fieldHitEnemy.getData('ImageKey')));
                this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setData(data);
                this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setData('NpcType', 'enemy');

                //名前の検索と設定
                const key = this.fieldHitEnemy.getData('ImageKey');
                const name = FieldEnemyNameData[key as keyof typeof FieldEnemyNameData];
                this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setData('name', name);
                this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setName(name);

                this.fieldHitEnemy.deleteCharacter();

            } else {
                //2体目以降
                const lamia = this.battleScene.add.image(0, 0, 'enemy01');

                lamia.name = 'enemy01';
                // lamia.npcType = 'enemy';
                // lamia.imageKey = 'enemy01';
                lamia.setData({
                    level: 2,
                    HP: 50,
                    MP: 0,
                    MaxHP: 50,
                    MaxMP: 0,
                    Attack: 40,//40
                    Guard: 1,
                    Speed: 5,
                    gold: 2
                });

                lamia.setData('NpcType', 'enemy');

                this.enemyPartyMap.set(lamia.name, lamia);

                //名前の検索と設定
                const key = lamia.name;
                const name = FieldEnemyNameData[key as keyof typeof FieldEnemyNameData];
                lamia.setData('name', name);

                this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setName(name);

            }
        }
    }

    //イベント戦闘の敵データを作成
    public createEventBattleEnemyData() {
        this.enemyPartyMap = new Map();

        //イベントから呼び出された場合、とりあえず一体のみ
        const lamy = this.battleScene.add.image(0, 0, 'enemy00');
        lamy.name = 'enemy00';
        const data: CharacterStatus = {
            level: this.fieldHitEnemy.getData('level'),
            HP: this.fieldHitEnemy.getData('HP'),
            MP: this.fieldHitEnemy.getData('MP'),
            MaxHP: this.fieldHitEnemy.getData('MaxHP'),
            MaxMP: this.fieldHitEnemy.getData('MaxMP'),
            Attack: this.fieldHitEnemy.getData('Attack'),
            Guard: this.fieldHitEnemy.getData('Guard'),
            Speed: this.fieldHitEnemy.getData('Speed'),
            gold: this.fieldHitEnemy.getData('gold')
        }

        lamy.setData(data);
        lamy.setData('NpcType', 'enemy');

        this.enemyPartyMap.set(lamy.name, lamy);

        //名前の検索と設定
        const key = lamy.name;
        const name = FieldEnemyNameData[key as keyof typeof FieldEnemyNameData];
        lamy.setData('name', name);

        this.enemyPartyMap.get(this.fieldHitEnemy.getData('ImageKey'))?.setName(name);
    }

    public getPartyList(): string[] { return this.partyList; }
    public getPlayerPartyList(): Phaser.GameObjects.Sprite[] { return this.playerPartyList; }
    public getEnemyList(): string[] { return this.enemyList; }

    public getNowSelectCharacterName(): string {
        return this.partyList[this.nowSelectPartyMemberNo];
    }

    public getNowSelectCharacterSprite(): Phaser.Physics.Arcade.Sprite {
        return this.characterGameObject.getSprite(this.gameScene, this.getNowSelectCharacterName());
    }

    //戦闘の選択継続のチェックと選択中キャラ番号の更新
    public continueBattleSelectAndUpadateSelectNo(): boolean {
        this.nowSelectPartyMemberNo++;
        if (this.partyList.length === this.nowSelectPartyMemberNo) {
            this.nowSelectPartyMemberNo = 0;
            return false;
        }
        return true;
    }

    public getSprite(characterName: string): Phaser.Physics.Arcade.Sprite {
        return this.characterGameObject.getSprite(this.gameScene, characterName);
    }

    public getCanNotRunaway(): boolean { return this.canNotRunaway; }

    public getPlayerParty(): Map<string, Phaser.GameObjects.Image> { return this.playerPartyMap; }
    public getEnemyParty(): Map<string, Phaser.GameObjects.Image> { return this.enemyPartyMap; }
    public getFieldHitEnemy(): Npc { return this.fieldHitEnemy }

    public getBattlerList() {

        //味方のマップを配列に変換
        const partyeList: Phaser.GameObjects.GameObject[] = []
        this.playerPartyMap.forEach(enemy => {
            partyeList.push(enemy);
        })

        //敵のマップを配列に変換
        const enemyList: Phaser.GameObjects.GameObject[] = []
        this.enemyPartyMap.forEach(enemy => {
            enemyList.push(enemy);
        })

        //プレイヤーパーティ＋敵の配列
        const battlerList = partyeList.concat(enemyList);
        return battlerList;
    }

    public setEnemyAttackTarget(characterIcon: Phaser.GameObjects.Image) {

        //ターゲットや攻撃方法の決定処理を作成する

        //現時点ではプレイヤーのみ対象
        this.enemyPartyMap.forEach(list => {

            //対象を決定
            //const playerPartyNum = new Phaser.Math.RandomDataGenerator().between(1, 2);
            const playerPartyNum = 0;

            Array.from(this.playerPartyMap.entries()).forEach(([key, value], index) => {
                if (index === playerPartyNum) {
                    // console.log(index, key, value);
                    list.setData('attackType', 'normal');
                    list.setData('BattleTarget', value);
                    list.setData('BattleTargetIcon', characterIcon);
                }
            });
        })
    }

    public deleteEnemy() {
        this.enemyPartyMap.forEach(enemy => {
            // enemy.getData('backGaugeHP').setVisible(false);
            // enemy.getData('gaugeHP').setVisible(false);
            enemy.destroy();
        })
    }

    public getUsePatern() {
        return this.usePatern;
    }

    public resetBattleStatus() {
        for (const partyMember of this.playerPartyMap.values()) {
            partyMember.data.remove('GuardValue');
            partyMember.data.remove('SkillType');
            partyMember.data.remove('UseSkill');
            partyMember.data.remove('BattleTarget');
            partyMember.data.remove('BattleTargetIcon');
            partyMember.data.remove('attackType');
        }
    }

}

import { BattleScene, ViewsContainer, SkillDetail } from "../../lib/types";
import { BattleModel } from "../model/BattleModel";
import { CommandSelectModel } from "../model/CommandSelectModel";
import { TurnModel } from "../model/TurnModel";
import { BattleSelectWindow } from "../view/BattleSelectWindow";
import { PlayerPartyWindow } from '../view/PlayerPartyWindow';
import { AttackSelectWindow } from "../view/AttackSelectWindow";
import { EnemySelectWindow } from "../view/EnemySelectWindow";
import { BattleMessageWindow } from '../view/BattleMessageWindow';
import { SpecialSkillSelectWindow } from "../view/SpecialSkillSelectWindow";
import { MagicSkillSelectWindow } from "../view/MagicSkillSelectWindow";

import { StateMachine } from "./StateMachine";

import PlayerAttack from "./PlayerAttack";
import PlayerGuard from "./PlayerGuard";
import EnemyAttack from "./EnemyAttack";

import { gameStateManager } from "../../GameAllState/GameStateManager";

import { Sound } from "../../scenes/Sound";

export class BattlePresenter {
    private battleScene: BattleScene;
    private soundScene: Sound;
    private endEvents: Phaser.Events.EventEmitter

    private battleModel: BattleModel;
    private commandSelectModel: CommandSelectModel;
    private turnModel: TurnModel;

    private battleSelectWindow: BattleSelectWindow;
    private playerPartyWindow: PlayerPartyWindow;
    private attackSelectWindow: AttackSelectWindow;
    private enemySelectWindow: EnemySelectWindow;
    private battleMessageWindow: BattleMessageWindow;
    private specialSkillSelectWindow: SpecialSkillSelectWindow;
    private magicSkillSelectWindow: MagicSkillSelectWindow;

    private views: ViewsContainer

    //履歴
    private stateMachine: StateMachine;

    constructor(
        battleScene: BattleScene,
        battleModel: BattleModel,
        commandSelectModel: CommandSelectModel,
        turnModel: TurnModel,

        battleSelectWindow: BattleSelectWindow,
        playerPartyWindow: PlayerPartyWindow,
        attackSelectWindow: AttackSelectWindow,
        enemySelectWindow: EnemySelectWindow,
        battleMessageWindow: BattleMessageWindow,
        specialSkillSelectWindow: SpecialSkillSelectWindow,
        magicSkillSelectWindow: MagicSkillSelectWindow
    ) {
        this.battleScene = battleScene;
        this.battleModel = battleModel;
        this.commandSelectModel = commandSelectModel;
        this.turnModel = turnModel;
        this.battleSelectWindow = battleSelectWindow;
        this.playerPartyWindow = playerPartyWindow;
        this.attackSelectWindow = attackSelectWindow;
        this.enemySelectWindow = enemySelectWindow;
        this.battleMessageWindow = battleMessageWindow;
        this.specialSkillSelectWindow = specialSkillSelectWindow;
        this.magicSkillSelectWindow = magicSkillSelectWindow;
    }

    public init() {
        this.soundScene = this.battleScene.scene.get('Sound') as Sound;

        this.commandSelectModel.setupTurnOrder(this.battleModel.getPlayerPartyList());
        this.battleSelectWindow.init();
        this.playerPartyWindow.init();
        this.attackSelectWindow.init();
        this.enemySelectWindow.init(this.battleModel.getEnemyParty());
        this.battleMessageWindow.init();
        this.specialSkillSelectWindow.init();
        this.magicSkillSelectWindow.init();
    }

    public async create(events: Phaser.Events.EventEmitter, views: ViewsContainer) {
        this.battleScene.game.events.emit('BGM_BATTLE', '');

        this.endEvents = events;

        this.views = views;

        //各viewのcreateを実行
        this.battleSelectWindow.createBattleSelectWindow(100, Number(this.battleScene.game.config.height) - 200);
        this.playerPartyWindow.createBattleCharacterIcon(this.battleModel.getPartyList(), 200, Number(this.battleScene.game.config.height) - 200);
        //AttackSelectWindowはinitでcreate実施
        //EnemySelectWindowはinitでcreate実施
        //battleMessageWindowはinitでcreate実施
        //specialSkillSelectWindowはinitでcreate実施

        //depth設定
        this.battleSelectWindow.setDepth(100);
        this.playerPartyWindow.setDepth(90);
        this.attackSelectWindow.setDepth(110);
        this.enemySelectWindow.setDepth(80);
        this.battleMessageWindow.setDepth(500);
        this.specialSkillSelectWindow.setDepth(120);
        this.magicSkillSelectWindow.setDepth(120);

        //履歴を管理し、戻る操作の際に履歴通りのウィンドウを表示するための機能
        this.stateMachine = new StateMachine(this.views);

        //各ビューの設定
        this.settingBattleSelectWindow();
        this.settingCharacterSelectWindow();
        this.settingAttackSelectWindow();
        this.settingSpecialSkillSelectWindow();
        this.settingMagicSkillSelectWindow();
        this.settingEnemySelectWindow();
        this.settingItemSelectWindow();

        //コマンド選択モデルのイベント設定
        this.setCommandSelectModel();

        //ターンモデルのイベント設定
        this.setTurnModel();

        // 初期遷移
        this.stateMachine.push('BATTLE_SELECT');

        //冒頭メッセージ
        await this.battleMessageWindow.messageOutput('敵が現れた！', 1000);
    }

    //設定：BattleSelectWindow
    private settingBattleSelectWindow() {

        // 表示・非表示設定
        this.stateMachine.addState('BATTLE_SELECT', {
            enter: (v) => {
                v.battleSelect.show();
                v.playerPartyWindow.show();
                v.attackSelect.hide();
            },
            exit: (v) => v.battleSelect.move()
        });

        //【戦闘選択】【戦う】
        this.views.battleSelect.on('Battle_Select_Submit', () => {//コールバック

            //次のコマンド選択キャラクターを取得しアイコンを点滅
            const character = this.commandSelectModel.getCurrentCharacter().name;
            const characterIcon = this.playerPartyWindow.getCharacterIcon(character);
            this.attackSelectWindow.setNowCharacterIcon(characterIcon);
            this.playerPartyWindow.lightUpDown(character);

            //攻撃方法選択ウィンドウに移動
            this.stateMachine.push('ATTACK_SELECT', this.commandSelectModel.getCurrentCharacter());
        });

        // シーン終了時にイベントを破棄
        this.battleScene.events.once('shutdown', () => {
            this.views.battleSelect.off('Battle_Select_Submit');

        });
    }

    //設定：CharacterSelectWindow
    private settingCharacterSelectWindow() {
        // キャラ選択はせず左から順番に処理するためアイコンは選択処理しない
        // this.stateMachine.addState('CHARACTER_ICON', {
        //     enter: (v) => v.main.show(),
        //     exit: (v) => v.main.hide()
        // });
    }

    //設定：AttackSelectWindow
    private settingAttackSelectWindow() {

        // 表示・非表示設定
        this.stateMachine.addState('ATTACK_SELECT', {
            enter: (v, data) => {
                // console.log("キャラクター:", data);
                v.attackSelect.show(data)
            },
            exit: (v) => v.attackSelect.hide()
        });

        //【攻撃方法選択】【攻撃】
        this.views.attackSelect.on('Attack_Select_Submit', (skillType: string) => {
            // switch (skillType) {
            //     case 'guard':
            //         break;
            //     default:
            //         this.stateMachine.push('ENEMY_SELECT');
            //         break;
            // }
            this.stateMachine.push('ENEMY_SELECT');
        });

        //【攻撃方法選択】【戻る】
        this.views.attackSelect.on('Select_back_Submit', () => {

            //点滅を停止
            const character = this.commandSelectModel.getCurrentCharacter().name;
            this.playerPartyWindow.deleteNowLightUpDown(character);//現状はプレイヤーのみ

            // 履歴を使って戻る
            this.stateMachine.pop();
            this.views.attackSelect.hide();
        });

        //【攻撃方法選択】【特技】
        this.views.attackSelect.on('SpecialSkill_Select_Submit', (nowSelectCharacter: Phaser.GameObjects.Sprite) => {
            console.log(this.commandSelectModel.getCurrentCharacter())

            //特技選択ウィンドウに渡すキャラクターアイコンを取得
            const character = this.commandSelectModel.getCurrentCharacter().name;
            const characterIcon = this.playerPartyWindow.getCharacterIcon(character);
            this.specialSkillSelectWindow.setNowCharacterIcon(characterIcon);

            this.stateMachine.push('SPECIAL_SKILL_SELECT', this.commandSelectModel.getCurrentCharacter());
        });

        //【攻撃方法選択】【魔法】
        this.views.attackSelect.on('MagicSkill_Select_Submit', (nowSelectCharacter: Phaser.GameObjects.Sprite) => {
            console.log(this.commandSelectModel.getCurrentCharacter())

            //魔法選択ウィンドウに渡すキャラクターアイコンを取得
            const character = this.commandSelectModel.getCurrentCharacter().name;
            const characterIcon = this.playerPartyWindow.getCharacterIcon(character);
            this.magicSkillSelectWindow.setNowCharacterIcon(characterIcon);

            this.stateMachine.push('MAGIC_SKILL_SELECT', this.commandSelectModel.getCurrentCharacter());
        });

        // シーン終了時にイベントを破棄
        this.battleScene.events.once('shutdown', () => {
            this.views.attackSelect.off('Attack_Select_Submit');
            this.views.attackSelect.off('Select_back_Submit');
            this.views.attackSelect.off('SpecialSkill_Select_Submit');
            this.views.attackSelect.off('MagicSkill_Select_Submit');
        });
    }

    //設定：SpecialSkillSelectWindow
    private settingSpecialSkillSelectWindow() {

        // 表示・非表示設定
        this.stateMachine.addState('SPECIAL_SKILL_SELECT', {
            enter: (v, data) => {
                // console.log("キャラクター:", data);
                v.specialSkillSelect.show(data)
            },
            exit: (v) => v.specialSkillSelect.hide()
        });

        //【特技選択】【特技】
        this.views.specialSkillSelect.on('Attack_Select_Submit', () => {
            this.stateMachine.push('ENEMY_SELECT');
        });

        //【特技選択】【攻撃しない】
        this.views.specialSkillSelect.on('No_Attack_Select_Submit', () => {
            this.stateMachine.push('BATTLE_START');
            this.commandSelectModel.nextTurn();
        });

        //【特技選択】【戻る】
        this.views.specialSkillSelect.on('Select_back_Submit', () => {

            // 履歴を使って戻る
            this.stateMachine.pop();
            this.views.specialSkillSelect.hide();
        });

        // シーン終了時にイベントを破棄
        this.battleScene.events.once('shutdown', () => {
            this.views.specialSkillSelect.off('Attack_Select_Submit');
            this.views.specialSkillSelect.off('Select_back_Submit');
        });
    }

    //設定：MagicSkillSelectWindow
    private settingMagicSkillSelectWindow() {

        // 表示・非表示設定
        this.stateMachine.addState('MAGIC_SKILL_SELECT', {
            enter: (v, data) => {
                // console.log("キャラクター:", data);
                v.magicSkillSelect.show(data)
            },
            exit: (v) => v.magicSkillSelect.hide()
        });

        //【魔法選択】【魔法】
