    private setCommandSelectModel() {

        //次キャラクターのコマンド選択
        this.commandSelectModel.on('CommandSelect', () => {

            //次のコマンド選択キャラクターを取得しアイコンを点滅
            const character = this.commandSelectModel.getCurrentCharacter().name;
            const characterIcon = this.playerPartyWindow.getCharacterIcon(character);
            this.attackSelectWindow.setNowCharacterIcon(characterIcon);
            this.playerPartyWindow.lightUpDown(character);

            this.stateMachine.push('ATTACK_SELECT');
        });

        //戦闘開始
        this.commandSelectModel.on('CommandSelectFinish', () => {

            //敵の攻撃対象を設定
            this.battleModel.setEnemyAttackTarget(this.playerPartyWindow.getCharacterIcon('player'));

            //ターン順を設定
            this.turnModel.setupTurnOrder(this.battleModel.getBattlerList());

            //戦闘処理
            this.battle(this.turnModel.getCurrentCharacter());
        });

        //イベントの破棄
        this.commandSelectModel.on('shutdown', () => {
            this.commandSelectModel.off('CommandSelect');
            this.commandSelectModel.off('CommandSelectFinish');
        });

    }

    //戦闘時のキャラクター毎のターンを管理する
    private setTurnModel() {

        //次キャラクターのターンへ変更
        this.turnModel.on('TurnChange', (currentActive: Phaser.GameObjects.GameObject) => {
            this.battle(currentActive);
        })

        //全てのキャラクターのターンが終了
        this.turnModel.on('TurnFinish', () => {

            //防御をリセット
            this.battleModel.resetBattleStatus();

            //最初のコマンドに戻る
            this.stateMachine.push('BATTLE_SELECT');
        })

        //イベントの破棄
        this.turnModel.on('shutdown', () => {
            this.turnModel.off('TurnChange');
            this.turnModel.off('TurnFinish');
        });

    }

    //現在ターンのキャラクターの攻撃処理
    async battle(battler: Phaser.GameObjects.GameObject) {
        gameStateManager.damage(100);
        let winner = '';

        //攻撃
        if (battler.getData('NpcType') !== 'enemy') {
            const skillDetail: SkillDetail = battler.getData('UseSkill');

            if (skillDetail) {
                switch (skillDetail.type) {
                    case 'attack':
                        const playerAttack = new PlayerAttack(this.battleScene);
                        await playerAttack.attack(this.battleMessageWindow, battler as Phaser.GameObjects.Sprite);
                        break;
                    case 'guard':
                        const playerGuard = new PlayerGuard(this.battleScene);
                        await playerGuard.guard(this.battleMessageWindow, battler as Phaser.GameObjects.Sprite);
                        break;
                    case 'heal':
                        /**未実装 */
                        break;
                }
            } else {
                const playerAttack = new PlayerAttack(this.battleScene);
                await playerAttack.attack(this.battleMessageWindow, battler as Phaser.GameObjects.Sprite);
            }

        } else if (battler.getData('NpcType') === 'enemy' && battler.data.values.HP > 0) {
            const enemyAttack = new EnemyAttack(this.battleScene);
            await enemyAttack.attack(this.battleMessageWindow, battler as Phaser.GameObjects.Image);
        }

        //味方のHPをチェック
        if (!this.checkPlayerStatus()) {
            console.log('enemy勝利')
            this.soundScene.stopAllBgm();
            winner = 'enemy';
        }

        //敵のHPをチェック
        if (!this.checkEnemyStatus()) {
            console.log('player勝利')
            this.soundScene.stopAllBgm();
            winner = 'player';
        }

        //勝利
        if (winner === 'player') {
            gameStateManager.addMoney(10);
            this.soundScene.SE_victory.play({ loop: false });

            //フィールドの敵を消去
            if (this.battleModel.getUsePatern() === 'normal') {
                this.battleModel.getFieldHitEnemy().deleteCharacter();
            }

            await this.battleMessageWindow.messageOutput('勝利！', 2000);

            this.endEvents.emit('BattleEnd');

        } else if (winner === 'enemy') {

            //フィールドの敵を消去
            if (this.battleModel.getUsePatern() === 'normal') {
                this.battleModel.getFieldHitEnemy().deleteCharacter();
            }

            await this.battleMessageWindow.messageOutput('ゲームオーバー', 1000);
            this.battleScene.scene.launch('GameOver');
            this.endEvents.emit('BattleEnd');
        }

        //ターンを更新
        if (!winner) {
            this.turnModel.nextTurn();
        }
    }

    private checkPlayerStatus() {
        let continueFlag = false;
        this.battleModel.getPlayerParty().forEach(list => {
            if (list.data.values.HP > 0) {
                continueFlag = true;
            }
        });
        return continueFlag;
    }

    private checkEnemyStatus() {
        let continueFlag = false;
        this.battleModel.getEnemyParty().forEach(list => {
            if (list.data.values.HP > 0) {
                continueFlag = true;
            }
        })
        return continueFlag;
    }



}

import { Sound } from "../../scenes/Sound";
import { BattleMessageWindow } from "../view/BattleMessageWindow";

export default class EnemyAttack {
    private battleScene: Phaser.Scene;
    private attacker: Phaser.GameObjects.Image;
    private target: Phaser.GameObjects.Sprite;

    private soundScene: Sound;

    //現状は単体選択のみ対応
    constructor(battleScene: Phaser.Scene) {
        this.battleScene = battleScene;
        this.soundScene = this.battleScene.scene.get('Sound') as Sound;
    }

    //仮、通常攻撃のエフェクトは別途作成する
    public attack(battleMessageWindow: BattleMessageWindow, attacker: Phaser.GameObjects.Image) {
        return new Promise<void>(resolve => {
            if (attacker.data.values.HP <= 0) return resolve();
            this.attacker = attacker;
            this.target = attacker.getData('BattleTarget');
            const targetIcon = attacker.getData('BattleTargetIcon');

            (async () => {
                await Promise.all([
                    battleMessageWindow.messageOutput(this.attacker.getData('name') + 'の攻撃！', undefined),
                    await this.attackTween(),
                    this.leanBack()
                ]);

                await Promise.all([
                    battleMessageWindow.messageOutput(this.target.getData('name') + 'に' + this.attacker.getData('Attack') + 'のダメージ！', undefined),
                    this.blinking(targetIcon)
                ]);

                //回避チェック
                if (this.target.getData('avoid')) {
                    battleMessageWindow.messageOutput(this.target.getData('name') + 'は回避した！', 600);
                    return;
                }

                //ガードチェック
                if (this.target.getData('guardPoint') > 0) {
                    battleMessageWindow.messageOutput(this.target.getData('name') + 'は防御した！', 600);
                    // this.target.setData('guardPoint', 0);
                }

                //ダメージ計算
                let GuardValue = 0;
                if (this.target.getData('GuardValue')) {
                    GuardValue = this.target.getData('GuardValue');
                }
                const damage = Math.max(this.attacker.getData('Attack') - GuardValue, 1);
                this.target.data.values.HP -= damage;
                if (this.target.data.values.HP <= 0) {
                    this.target.data.values.HP = 0;
                }

                //攻撃対象を初期化
                this.attacker.setData('BattleTarget', undefined);

                await new Promise<void>(resolve => {
                    this.battleScene.time.delayedCall(500, () => {
                        resolve();
                    }, [], this.battleScene);
                })

                resolve();
            })();
        })
    }

    //通常攻撃エフェクト
    private attackTween() {
        console.log('attackTween')
        return new Promise<void>(resolve => {
            const tween = this.battleScene.tweens.add({
                targets: this.attacker,
                scale: this.attacker.scaleX + 0.02,
                ease: 'sine.inout',
                yoyo: true,
                duration: 100,
                delay: 500,
                onComplete: () => {
                    resolve();
                    // tween.destroy();
                }
            });
        })
    }

    //画面効果
    private leanBack() {
        this.soundScene.SE_punch.play();
        return new Promise<void>(resolve => {
            this.battleScene.cameras.main.shake(100, 0.02);
            this.battleScene.time.delayedCall(500, () => {
                resolve();
            }, [], this.battleScene);
        });
    }

    //相手点滅
    private blinking(target: Phaser.GameObjects.Image) {
        this.soundScene.SE_attack.play();

        return new Promise<void>(resolve => {
            let flag = true;
            const timer = this.battleScene.time.addEvent({
                delay: 100,
                callback: () => {
                    if (flag) {
                        flag = !flag;
                        target.setAlpha(0.5);
                    } else {
                        flag = !flag;
                        target.setAlpha(1);
                    }
                    if (timer.repeatCount === 0) {
                        // this.soundScene.attackSE.stop();
                        resolve();
                    }
                },
                callbackScope: this.battleScene,
                repeat: 3,
            });
        })
    }

}

import { Sound } from "../../scenes/Sound";
import { MagicFrame } from "../../util/Effect/MagicFrame";
import { SkillDetail } from "../../lib/SkillDataTypes";
import { BattleMessageWindow } from "../view/BattleMessageWindow";
import { NormalAttack } from "../../util/Effect/NormalAttack";

export default class PlayerAttack {
    private battleScene: Phaser.Scene;
    private attacker: Phaser.GameObjects.Sprite;
    private targetEnemy: Phaser.GameObjects.Image;
    attackDuration = 300;

    private soundScene: Sound;

    //現状は単体選択のみ対応
    constructor(battleScene: Phaser.Scene) {
        this.battleScene = battleScene;

        //BGM開始はNpcCommonで実行しているが、sceneと役割を考えると改良した方が良い
        this.soundScene = this.battleScene.scene.get('Sound') as Sound;
    }

    //仮、通常攻撃のエフェクトは別途作成する
    //攻撃者のデータから目標を取得して処理する
    public attack(battleMessageWindow: BattleMessageWindow, attacker: Phaser.GameObjects.Sprite) {
        return new Promise<void>(resolve => {

            if (attacker.data.values.HP <= 0) return resolve();
            this.attacker = attacker;
            this.targetEnemy = attacker.getData('BattleTarget');

            const worldPoint = this.targetEnemy.getWorldTransformMatrix().transformPoint(0, 0);
            const targetX = worldPoint.x + (this.targetEnemy.width / 2);
            const targetY = worldPoint.y + (this.targetEnemy.height / 2);

            const skillType = this.attacker.getData('SkillType');
            const skillDetail: SkillDetail = this.attacker.getData('UseSkill');

            (async () => {
                await Promise.all([
                    battleMessageWindow.messageOutput(this.attacker.getData('name') + 'の攻撃！', undefined),

                    (() => {
                        if (skillType) {
                            switch (skillType) {
                                case 'special':

                                case 'magic':
                                    const effect = new MagicFrame(this.battleScene, targetX, targetY, this.attackDuration, undefined);
                                    return Promise.all([
                                        effect.attackAnimation(),
                                        this.attackTween(effect),
                                    ])
                                default:
                                    return Promise.resolve();
                            }
                        } else {
                            const effect = new NormalAttack(this.battleScene, targetX, targetY, this.attackDuration, undefined);
                            return Promise.all([
                                effect.attackAnimation(),
                                this.normalAttackTween(effect),
                            ])
                        }
                    })(),

                    this.leanBack(this.targetEnemy)
                ]);
                await Promise.all([
                    battleMessageWindow.messageOutput(this.targetEnemy.getData('name') + 'に' + this.attacker.getData('Attack') + 'のダメージ！', undefined),
                    this.blinking(this.targetEnemy)
                ]);

                //計算処理
                this.targetEnemy.data.values.HP -= this.attacker.getData('Attack');

                //HPチェック
                if (this.targetEnemy.data.values.HP <= 0) {
                    this.targetEnemy.data.values.HP = 0;
                    battleMessageWindow.messageOutput(this.targetEnemy.getData('name') + 'を倒した！', 600);
                    await this.deleteEnemy(this.targetEnemy);
                }

                //攻撃対象を初期化
                this.attacker.setData('BattleTarget', undefined);

                await new Promise<void>(resolve => {
                    this.battleScene.time.delayedCall(600, () => {
                        resolve();
                    }, [], this.battleScene);
                })

                resolve();
            })();
        })
    }

    //攻撃エフェクト
    private attackTween(effect: Phaser.GameObjects.Sprite) {
        this.soundScene.SE_fire.play();
        return new Promise<void>(resolve => {
            const tween = this.battleScene.tweens.add({
                targets: effect,
                scale: 2,
                ease: 'sine.inout',
                repeat: 2,
                yoyo: true,
                duration: this.attackDuration,
                onComplete: () => {
                    resolve();
                    this.soundScene.SE_fire.stop();
                    tween.destroy();
                }
            });
        })
    }

    private normalAttackTween(effect: Phaser.GameObjects.Sprite) {
        this.soundScene.SE_attack6.play({ loop: true });
        return new Promise<void>(resolve => {
            const tween = this.battleScene.tweens.add({
                targets: effect,
                scale: 2,
                ease: 'sine.inout',
                repeat: 1,
                duration: 180,
                onComplete: () => {
                    resolve();
                    this.soundScene.SE_attack6.stop();
                    tween.destroy();
                }
            });
        })
    }

    //相手仰け反り
    private leanBack(enemy: Phaser.GameObjects.Image) {
        return new Promise<void>(resolve => {
            const tween = this.battleScene.tweens.add({
                targets: enemy,
                y: enemy.y - 20,
                ease: 'sine.inout',
                duration: 100,
                yoyo: true,
                onComplete: () => {
                    resolve();
                    tween.destroy();
                }
            });
        });
    }

    //相手点滅
    private blinking(enemy: Phaser.GameObjects.Image) {
        this.soundScene.SE_attack.play();
        return new Promise<void>(resolve => {
            let flag = true;
            const timer = this.battleScene.time.addEvent({
                delay: 100,
                callback: () => {
                    if (flag) {
                        flag = !flag;
                        enemy.setAlpha(0.5);
                    } else {
                        flag = !flag;
                        enemy.setAlpha(1);
                    }
                    if (timer.repeatCount === 0) {
                        // this.soundScene.attackSE.stop();
                        resolve();
                    }
                },
                callbackScope: this.battleScene,
                repeat: 3,
            });
        })
    }

    //フェードアウト
    private deleteEnemy(target: Phaser.GameObjects.Image) {
        return new Promise<void>(resolve => {
            this.battleScene.tweens.addCounter({//このtweenはオブジェクトをターゲットとせず、設定した値を更新し続ける
                from: 1,
                to: 0,
                duration: 100,
                ease: 'linear',
                onUpdate: (tween) => {
                    //取得した値をセットする
                    target.setAlpha(tween.getValue()!);
                    target.getData('backGaugeHP').setAlpha(tween.getValue());
                    target.getData('gaugeHP').setAlpha(tween.getValue());
                    resolve();
                },
            });
        })
    }
}

import { BattleScene } from "../../lib/types";
import { MessageObject } from "../../util/MessageObject";
import { MessageWindow } from "../../util/MessageWindow";
import { SelectAllow } from "../../util/SelectAllow";
import DebugMessage from "../../util/DebugMessage";

export class AttackSelectWindow extends Phaser.GameObjects.Container {
    private nowSelectCharacter: Phaser.GameObjects.Sprite;

    private column: string[] = ['攻撃', '特技', '魔法'];
    private selectList: Phaser.GameObjects.Text[] = [];

    private nowSelectNo = 0;

    private columnWindow: MessageWindow;
    private allow: SelectAllow;
    private backButton: Phaser.GameObjects.Text;
    private backButtonWindow: MessageWindow;

    private characterIcon: Phaser.GameObjects.Image;

    constructor(battleScene: BattleScene) {
        super(battleScene);
        this.scene.add.existing(this);
        this.addToUpdateList();
        this.name = AttackSelectWindow.name;
    }

    init() {
        this.x = 0;
        this.y = 0;
        this.name = AttackSelectWindow.name;
        this.createWindow(this.column);
    }

    preUpdate() {
        this.updateSelectNo();
    }

    private createWindow(column: string[]) {

        const messageObjectInstance = new MessageObject();
        messageObjectInstance.init(this.scene);
        messageObjectInstance.getTextInfomation();

        this.backButton = messageObjectInstance.createTextObject(this.scene, 80, -48, "✖");
        this.backButton.setDepth(Number(this.scene.game.config.height) + 1);
        this.backButton.setInteractive({ useHandCursor: true });
        this.backButton.on('pointerdown', () => {
            this.emit('Select_back_Submit', 0);
            this.nowSelectNo = 0;
        }, this);

        this.backButtonWindow = new MessageWindow(this.scene);
        this.backButtonWindow.init();
        this.backButtonWindow.createOneColumnOneWindow(this.backButton, 16);


        //項目テキスト作成
        column.forEach(str => {
            const messagaObject = messageObjectInstance.createTextObject(this.scene, 0, 0, str)
            messagaObject.name = str;
            this.selectList.push(messagaObject);
        });

        //テキスト配置及びクリック時の動作を設定
        this.selectList.forEach((obj, index) => {
            obj.y = index * (obj.height + messageObjectInstance.getTextInfomation().lineSpaceValue);

            obj.on('pointerover', () => {
                this.allow.updatePosition(obj);
                this.nowSelectNo = index;
            }, this);

            obj.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
                pointer.reset();//入力状態をリセット、リセットしないと押下中に連続で処理される
                this.selectExec(index);
                this.scene.input.setDefaultCursor('default');//ポインターをデフォルトに設定
            }, this);
        });

        //ウィンドウ作成
        this.columnWindow = new MessageWindow(this.scene);
        this.columnWindow.init();
        this.columnWindow.createVerticalColumnWindow(this.selectList, 16);

        //カーソル作成配置
        this.allow = new SelectAllow(this.scene);
        this.allow.init(0, 0)
        this.allow.createAllow();
        this.allow.updatePosition(this.selectList[this.nowSelectNo]);

        //コンテナ作成
        this.add(this.columnWindow);
        this.add(this.selectList);
        this.add(this.allow);
        this.add(this.backButtonWindow);
        this.add(this.backButton);

        //クリック可能に設定
        this.enableSelect();

        this.setVisible(false);
    }

    //選択実行
    private selectExec(index: number) {

        switch (index) {
            case 0: //攻撃、敵キャラを選択
                this.emit('Attack_Select_Submit', this.nowSelectCharacter);
                break;
            case 1: //特技、次ウィンドウを開く
                this.emit('SpecialSkill_Select_Submit', this.nowSelectCharacter);
                break;
            case 2: //魔法、次ウィンドウを開く
                this.emit('MagicSkill_Select_Submit', this.nowSelectCharacter);
                break;
        }
    }

    //選択中のアイコンを設定
    public setNowCharacterIcon(characterIcon: Phaser.GameObjects.Image) {
        this.characterIcon = characterIcon;
    }

    show(data: Phaser.GameObjects.Sprite) {

        this.nowSelectCharacter = data;

        this.setVisible(true);
        this.enableSelect();

        //コンテナ配置（キャラクターアイコンの近くに配置）
        this.x = this.characterIcon.parentContainer.x + 200;
        this.y = this.characterIcon.parentContainer.y - 75;
    }

    move() {
        this.disableSelect();
    }

    hide() {
        this.setVisible(false);
    }

    private updateSelectNo() {
        const minNo = 0;
        const maxNo = this.selectList.length;
        let selectText = null;
        const cursor: Phaser.Types.Input.Keyboard.CursorKeys = (this.scene as BattleScene).getCursorsKeys();

        //キー押下でリストの選択番号を更新する
        if (cursor.down.isDown) {
            //更新後の選択番号がリスト番号の最大値を超える場合
            if (this.nowSelectNo + 1 >= maxNo) { return; }
            cursor.down.isDown = false;
            this.nowSelectNo++;
            selectText = this.selectList[this.nowSelectNo];
            this.allow.updatePosition(selectText);
        } else if (cursor.up.isDown) {
            //更新後の選択番号がリスト番号の最小値を超える場合
            if (this.nowSelectNo - 1 < minNo) { return; }
            cursor.up.isDown = false;
            this.nowSelectNo--;
            selectText = this.selectList[this.nowSelectNo];
            this.allow.updatePosition(selectText);
        }
    }

    //テキストクリック可
    enableSelect() {
        this.allow.lightUp();
        this.lightUp();
        this.setVisible(true);
        this.selectList.forEach((obj) => {
            obj.setInteractive({ useHandCursor: true });//テキストをクリック可能にする
        });
    }

    //テキストクリック不可
    disableSelect() {
        this.allow.lightDown();
        this.lightDown();
        this.selectList.forEach(obj => {
            obj.disableInteractive();
        });
        this.backButton.disableInteractive();
    }

    //テキストクリック不可、ウィンドウ非表示
    deleteSelect() {
        this.setVisible(false);
        this.selectList.forEach(obj => {
            obj.disableInteractive();
        });
