/**
 * Phaserのライフサイクルと事前処理について
 * Scene作成時、コンストラクタの後にライフサイクルによる事前処理が存在する。
 * ・constructor()→init()→preload()→create()
 * constructor()の時点ではPhaser基盤作成中のような状態でゲームオブジェクトも存在しない場合がある。
 * そのため、純粋なデータ等はinit()で保存処理、ゲームのオブジェクト作成等はcreate()で処理する事。
 * constructor()では基本的に処理しない。
 */

import { Npc } from "../gamemain/view/character/Npc";
import { GameScene } from "../lib/types";

export class CharacterGameObject {
    private characterImageMap: Map<string, Phaser.GameObjects.Image> = new Map();

    constructor() { }

    //spriteを検索
    public getSprite(gameScene: GameScene, characterName: string): Phaser.Physics.Arcade.Sprite {

        let characterSprite: Phaser.Physics.Arcade.Sprite;
        const displayList = gameScene.children.getChildren();

        try {
            displayList.map(obj => {
                if (obj.type === "Sprite") {
                    if (obj.name === characterName) {//動かすキャラはここで指定する
                        characterSprite = obj as Phaser.Physics.Arcade.Sprite;
                    }
                }
            })
        } catch {
            console.log('検索Execption' + characterName)
        }
        return characterSprite!;
    }

    //パーティリストを取得
    public getPlayerPartyList(gameScene: GameScene): Phaser.GameObjects.Sprite[] {
        return gameScene.getMapObject().getPlayerPartyList();
    }

    //フィールドの敵リストを取得
    public getFieldEnemyList(gameScene: GameScene): Npc[] {
        return gameScene.getMapObject().getFieldEnemyList();
    }

    //キャラクターの立ち絵を取得
    public setCharacterImage(scene: Phaser.Scene, initX: number, initY: number, characterKey: string, characterImageKey: string, moveToX: number, scale: number, duration: number) {
        return new Promise<void>(resolve => {
            //setTintでグレーに設定、Phaser.Display.Color.GetColor()でRGB指定が可能
            const characterimage = scene.add.image(initX, initY, characterImageKey).setScale(scale);
            characterimage.setTint(Phaser.Display.Color.GetColor(128, 128, 128));
            this.characterImageMap.set(characterKey, characterimage);

            //画面外からスクロール
            scene.tweens.add({
                targets: characterimage,
                x: moveToX,
                ease: 'sine.out',
                duration: duration,
                onComplete: () => {
                    resolve();
                }
            });
        })
    }

    public getCharacterImage(characterKey: string): Phaser.GameObjects.Image {
        return this.characterImageMap.get(characterKey)!;
    }

    //会話中のキャラクターをライトアップ
    public lightUp(characterKey: string) {
        const characterImage = this.characterImageMap.get(characterKey);

        //ライトアップダウンの色合い設定
        const lightUpRGB = 255;
        const lightDownRGB = 128;

        return new Promise<void>(resolve => {
            //このtweenはオブジェクトをターゲットとせず、内部で値を更新し続ける
            //※削除処理は考えるべき
            const updateTween = characterImage!.scene.tweens.addCounter({
                from: lightDownRGB,
                to: lightUpRGB,
                duration: 100,
                ease: 'linear',
                onUpdate: (tween) => {
                    //このtweenから値を取得する
                    const value = Math.floor(tween.getValue()!);

                    //取得した値をセットする
                    characterImage!.setTint(Phaser.Display.Color.GetColor(value, value, value));
                },
                onComplete: () => {
                    resolve();
                }
            });
        })
    }

    //未会話のキャラクターをライトダウン
    lightDownOtherCharacters(characterKey: string) {
        for (const [key, image] of this.characterImageMap) {

            //ライトアップダウンの色合い設定
            const lightUpRGB = 255;
            const lightDownRGB = 128;

            if (characterKey !== key) {
                return new Promise<void>(resolve => {
                    //このtweenは値を保持し更新し続ける。
                    //※削除処理は考えるべき
                    const updateTween = image.scene.tweens.addCounter({
                        from: lightUpRGB,
                        to: lightDownRGB,
                        duration: 100,
                        ease: 'linear',
                        onUpdate: (tween) => {
                            //このtweenから値を取得する
                            const value = Math.floor(tween.getValue()!);

                            //取得した値をセットする
                            image.setTint(Phaser.Display.Color.GetColor(value, value, value));
                        },
                        onComplete: () => {
                            resolve();
                        }
                    });
                })
            }
        }
    }
}

export class EnergyGauge extends Phaser.GameObjects.Graphics {
    //gaugeHP,gaugeCaseHP,gaugeMP,gaugeCaseMP
    private characterObject: Phaser.Physics.Arcade.Sprite | Phaser.GameObjects.Image;

    private rectR: number;
    private value: number;
    private maxValue: number;
    private width: number;
    private height: number;

    constructor(scene: Phaser.Scene, characterObject: Phaser.Physics.Arcade.Sprite | Phaser.GameObjects.Image, type: string) {
        super(scene);
        this.scene = scene;
        this.characterObject = characterObject;
        this.name = characterObject.name;
        this.type = type;
        this.scene.add.existing(this);
        this.addToDisplayList();
        this.createGauge();
    }

    preUpdate(time: number, delta: number) {
        this.gauge();
    }

    private createGauge() {
        try {
            this.gauge();
            this.gaugeCase();
            if (this.type !== 'HP' && this.type !== 'MP' && this.type !== 'MaxHP' && this.type !== 'MaxMP') {
                throw new Error(`type is missing`);
            }
        } catch (error) {
            console.log(error); //try chatchやりたかった
        }
    }

    private gauge() {
        if (this.type !== 'HP' && this.type !== 'MP') return;
        this.clear();//再描画のためクリア

        const value = this.type === 'HP' ? this.characterObject.getData('HP') : this.characterObject.getData('MP');
        const maxValue = this.type === 'HP' ? this.characterObject.getData('MaxHP') : this.characterObject.getData('MaxMP');

        const rectR = this.rectR ? this.rectR : 4;//角の丸みの半径
        const maxWidth = this.width ? this.width : 100 + rectR * 2;
        const nowGageHeight = this.height ? this.height : 16 + rectR * 2;

        const nowGageWidth = maxWidth * value / maxValue;

        let color;
        if (this.type === 'HP') {
            color = 0x3cb371;
        } else {
            color = 0x4169e1;
        }

        if (this.type === 'HP' && value / maxValue <= 4 / 10) {
            color = 0xdc143c;
        }

        this.fillStyle(color);
        this.fillRoundedRect(-1 * rectR, -1 * rectR, nowGageWidth, nowGageHeight, rectR);

        this.width = maxWidth;
        this.height = nowGageHeight;
    }

    //ゲージの縁
    //同時に作成すると上書きになるため別々にインスタンス化する事
    private gaugeCase() {
        if (this.type !== 'MaxHP' && this.type !== 'MaxMP') return;
        this.clear();//再描画のためクリア

        const rectR = this.rectR ? this.rectR : 4;//角の丸みの半径
        const maxWidth = this.width ? this.width : 100 + rectR * 2;
        const GageHeight = this.height ? this.height : 16 + rectR * 2;

        this.fillStyle(0x000000, 1);
        this.lineStyle(3, 0x000000);
        this.fillRoundedRect(-1 * rectR, -1 * rectR, maxWidth, GageHeight, rectR);
        this.strokeRoundedRect(-1 * rectR, -1 * rectR, maxWidth, GageHeight, rectR);

        this.width = maxWidth;
        this.height = GageHeight;
    }

    setRectR(rectR: number) {
        this.rectR = rectR;
        this.gauge();
        this.gaugeCase();
    }

    setWidth(width: number) {
        const rectR = this.rectR ? this.rectR : 4;//角の丸みの半径
        this.width = width + rectR * 2;
        this.gauge();
        this.gaugeCase();
    }

    setHeight(height: number) {
        const rectR = this.rectR ? this.rectR : 4;//角の丸みの半径
        this.height = height + rectR * 2;
        this.gauge();
        this.gaugeCase();
    }

    public getWidth() { return this.width; }
    public getHeight() { return this.height; }
}

import { EventScene, GameScene } from "../lib/types";
